function UIBattlingPVPInfoDialog:InitComp()
    -- local isShowTxtRoomId = BattleInfo.gameMode == Constants.GameMode.PVP
    -- KTool.SetActive(self.Txt_RoomId.gameObject, isShowTxtRoomId)
    local isShowTimer = UIBattleSettingMgr.showRemainTime
    KTool.SetActive(self.PVPTimerNode.gameObject, isShowTimer)

    local LB_PlayerHeadNode1 = GetLuaBehaviour(self.RT_PlayerHeadNode1.gameObject, LUA_PATH_PLAYER_HEAD_NODE)
    local LT_PlayerHeadNode1 = LB_PlayerHeadNode1.Env
    local LB_PLayerHeadNode2 = GetLuaBehaviour(self.RT_PlayerHeadNode2.gameObject, LUA_PATH_PLAYER_HEAD_NODE)
    local LT_PlayerHeadNode2 = LB_PLayerHeadNode2.Env

    local isMyPlayerOnTheLeft = UIBattlingTools.GetMyPlayerDirection() == 0
    self.LT_MyPlayerHeadNode = isMyPlayerOnTheLeft and LT_PlayerHeadNode2 or LT_PlayerHeadNode1
    self.LT_OtherPlayerHeadNode = isMyPlayerOnTheLeft and LT_PlayerHeadNode1 or LT_PlayerHeadNode2

    -- 初始化先后手标识 队友标识
    self:InitTeammeatIconState()
    -- 初始化玩家头像
    self:InitPlayersInfo()

    -- 点击对方头像显示个人信息
    if UIBattlingTools:GetMyCampPlayerCount() > 1 then
        local otherPlayerDesc = UIBattlePlayerInfoMgr:GetOtherPlayerDesc()
        local playerId = checkNumber(otherPlayerDesc.playerId)
        self.LT_OtherPlayerHeadNode:SetOnClickCallback(function()
            if playerId > 0 then  -- 机器人不能点
                GameUtils.ShowPlayerInfo(playerId)
            end
        end)
    end
    
    if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PPVE then
        -- 先判断一下有没有队友，没有的话把头像隐藏
        if UIBattlingTools:GetMyCampPlayerCount() == 1 then
            -- PPVE模式可以单人开始，单人开始的话不显示头像
            self:SetPlayerHeadNodeState(false)
        else
            -- PPVE模式，把左上角的玩家头像移动到左下角
            KTool.SetParent(self.RT_PlayerHeadNode2.gameObject, self.RT_LeftBottomPanel.gameObject)
            self.RT_PlayerHeadNode2.anchorMin = Vector2.New(0.5, 0.5)
            self.RT_PlayerHeadNode2.anchorMax = Vector2.New(0.5, 0.5)
            self.RT_PlayerHeadNode2.anchoredPosition = Vector3.New(-415, -45, 0)

            -- 打开左下角UI自适应的占位符
            local UIBattlingCtrlMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
            local dialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
            KTool.SetActive(dialog.RT_OnlinePVEPlaceHolder, true)

            local useVoiceRoom = BattleViewMgr.useVoiceRoom

            KTool.SetActive(self.CommonVoiceChatBtn, useVoiceRoom)
            if useVoiceRoom then
                -- 初始化麦克风状态节点
                LT_PlayerHeadNode1:ShowMicStateNode(0)
                LT_PlayerHeadNode2:ShowMicStateNode(1)
                
                -- 初始化我自己的聊天麦克风开关
                local lb = GetLuaBehaviour(self.CommonVoiceChatBtn.gameObject, "Game.Behaviours.CommonMicBtn")
                lb.Env:SetPlayerId(checkNumber(GameUtils.GetPlayerId()))
                -- 把麦克风开关移动到我这一边
                local micStateNodeRoot = self.LT_MyPlayerHeadNode:GetMicStateNodeRoot(isMyPlayerOnTheLeft and 1 or 0)
                KTool.SetParent(self.CommonVoiceChatBtn.gameObject, micStateNodeRoot.gameObject)
                self.CommonVoiceChatBtn.anchorMin = Vector2.New(0.5, 0.5)
                self.CommonVoiceChatBtn.anchorMax = Vector2.New(0.5, 0.5)
                self.CommonVoiceChatBtn.anchoredPosition = Vector3.New(isMyPlayerOnTheLeft and 55 or -55, 0, 0)
            end
        end
    end

    if UIBattleSettingMgr.canSendEmoji then
        --- 表情列表
        if not IsNull(self.MessageSelectRoot) then
            self.MessageSelectRoot:Init()
            self.LT_EmojiMSGSelect = self.MessageSelectRoot.Env
        end
        -- 修改消息出现的方向，表情框的箭头方向
        LT_PlayerHeadNode1:SetEmojiMsgRootDirection(0)
        LT_PlayerHeadNode2:SetEmojiMsgRootDirection(1)
        LT_PlayerHeadNode1:SetEmojiFrameIndex(5)
        LT_PlayerHeadNode2:SetEmojiFrameIndex(2)
        -- 如果我在右边，那表情选择菜单也移动到右边
        if not isMyPlayerOnTheLeft then
            local panel = self.MessageSelectRoot.transform:Find("SelectPanel/PanelBg")
            panel.anchorMin = Vector2.New(1, 0)
            panel.anchorMax = Vector2.New(1, 0)
            panel.anchoredPosition = Vector3.New(-720, 168, 0)
            -- print("[歼灭战] 移动表情选择菜单位置", old, self.MessageSelectRoot.transform.anchoredPosition)
        end
    end

    -- 敌人的技能卡池
    if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        self:FillEnemySkillCard()
        self:ResetSkillCards()
    else
        KTool.SetActive(self.RT_EnemySkillPool.gameObject, false)
    end
    
    -- 战斗回看中
    if LadderStruggleMgr and LadderStruggleMgr:IsRecordReplay() then
        KTool.SetActive(self.RT_Subtitles, true)
    end

    -- 关闭属性克制按钮
    local UIBattlingCtrlMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
    local dialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    KTool.SetActive(dialog.AttributeCircleBtn, false)
end

function UIBattlingPVPInfoDialog:InitListener()
    if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        self.eventBattleTurnStart = Events.AddListener(Constants.EventNames.BattleTurnStartShow, Bind(self, self.ActionOnRoundStart))
        self.eventBattleEnemyCard = Events.AddListener(Constants.EventNames.BattleEnemyCard, Bind(self, self.DOFuncAtBattleMyCard))
        self.eventUpdateSkillCardUsedState = Events.AddListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, Bind(self, self.UpdateListSkillSeqState))
        self.eventBattleRequireInput = Events.AddListener(Constants.EventNames.BattleRequireInput, Bind(self, self.ActionOnBattleRequireInput))
        self.eventAllCampInputFinish = Events.AddListener(Constants.EventNames.BattlePlayerInputFinish, Bind(self, self.ActionOnAllCampInputFinish))
    elseif UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PPVE then
        self.eventBattleRequireInput = Events.AddListener(Constants.EventNames.BattleRequireInput, Bind(self, self.ActionOnBattleRequireInput))
        self.eventAllCampInputFinish = Events.AddListener(Constants.EventNames.BattlePlayerInputFinish, Bind(self, self.ActionOnAllCampInputFinish))
    end
    if UIBattleSettingMgr.canSendEmoji then
        self.eventSelectEmoji = Events.AddListener(Constants.EventNames.UIBattlingSelectEmoji, Bind(self, self.SetOurEmoji))
        self.eventReceiveEmoji = Events.AddListener(Constants.EventNames.BattleReceiveEmoji, Bind(self, self.SetEnemyEmoji))
        self.LT_MyPlayerHeadNode:SetOnClickCallback(function()
            if not isNull(self.LT_EmojiMSGSelect) then
                self.LT_EmojiMSGSelect:ShowPanel()
            end
        end)
    end
    
    self.eventOnReceivePackage = Events.AddListener(Constants.EventNames.BattleNetworkOnReceived, Bind(self, self.OnReceivedPackage))
end

function UIBattlingPVPInfoDialog:RemoveListener()
    if self.eventBattleTurnStart then
        Events.RemoveListener(Constants.EventNames.BattleTurnStartShow, self.eventBattleTurnStart)
    end
    if self.eventBattleEnemyCard then
        Events.RemoveListener(Constants.EventNames.BattleEnemyCard, self.eventBattleEnemyCard)
    end
    if self.eventUpdateSkillCardUsedState then
        Events.RemoveListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, self.eventUpdateSkillCardUsedState)
    end
    if self.eventSelectEmoji then
        Events.RemoveListener(Constants.EventNames.UIBattlingSelectEmoji, self.eventSelectEmoji)
    end
    if self.eventReceiveEmoji then
        Events.RemoveListener(Constants.EventNames.BattleReceiveEmoji, self.eventReceiveEmoji)
    end
    if self.eventOnReceivePackage then
        Events.RemoveListener(Constants.EventNames.BattleNetworkOnReceived, self.eventOnReceivePackage)
    end
    if self.eventBattleRequireInput then
        Events.RemoveListener(Constants.EventNames.BattleRequireInput, self.eventBattleRequireInput)
    end
    if self.eventAllCampInputFinish then
        Events.RemoveListener(Constants.EventNames.BattlePlayerInputFinish, self.eventAllCampInputFinish)
    end
end

