---FillEnemySkillCard
---填充 敌方技能卡 序列
function UIBattlingPVPInfoDialog:FillEnemySkillCard()
    self.listEnemySkillCard = {}
    self.listSISkillCardLocal = {}
    --self.listNodeSkillMask = {}
    self.listWaittingNode = {}
    if not IsNull(self.RT_EnemySkillPool)  then
        for i = 1, self.RT_EnemySkillPool.childCount do
            local childNodeName = string.format("Card_%d",i)
            local transChild = self.RT_EnemySkillPool:Find(childNodeName)
            if not IsNull(transChild) then
                
                local siSkillLocal = transChild.gameObject:GetComponent(typeof(UISwitchImage))
                if not IsNull(siSkillLocal) then
                    table.insert(self.listSISkillCardLocal, siSkillLocal)
                end
                
                --local transSkillCardMask =  transChild:Find("PVPShowCardNode")
                --if not IsNull(transSkillCardMask) then
                --    table.insert(self.listNodeSkillMask, transSkillCardMask.gameObject)
                --end
                
                local transSkillCardMB =  transChild:Find("SkillCardNodeSmall")
                if not IsNull(transSkillCardMB) then
                    local luaB = GetLuaBehaviour(transSkillCardMB.gameObject, Constants.UIBattlingLuaTablePath.SkillCardsSmall)
                    if luaB then
                        luaB:Init()
                        local skillCard = luaB.Env
                        table.insert(self.listEnemySkillCard, skillCard)
                    end
                end

                local waittingNode =  transChild:Find("WaitingNode")
                if not isNull(waittingNode) then
                    table.insert(self.listWaittingNode, waittingNode)
                end
            end
        end
    end
end

