function UIBattlingPVPInfoDialog:UpgradeSkillCardSequenceBGState()
    if isNull(self.listSISkillCardLocal) then
        return
    end
    local _APEnemy = UIBattlingPVPMgr.enemyActionPoint
    for i, comp in pairs(self.listSISkillCardLocal) do
        comp.Status = (i > _APEnemy) and 2 or 1
        comp:Reset()
    end
    --for i, skillMask in pairs(self.listNodeSkillMask) do
    --    KTool.SetActive(skillMask, (i <= _APEnemy))
    --end
end

function UIBattlingPVPInfoDialog:UpdateListSkillSeqState(roleId)
    local roleView = UIBattlingTools.GetRoleViewData(roleId)
    if roleView then
        local roleCampType = roleView.camp
        local isDead = roleView:IsDead()
        if not BattleInfo:IsUserCamp(roleCampType) and isDead then
            if isNull(self.listEnemySkillCard) then return end
            for i, skillCard in pairs(self.listEnemySkillCard) do
                local idData = skillCard.skillCardRoleId
                if idData == roleId then
                    skillCard:SetDeadState()
                end
            end
        end
    end
end

function UIBattlingPVPInfoDialog:ActionOnTurnStart()
    self.indexAnimationName = 0
    self.curAction = 0
    self:ResetSkillCards()
end

function UIBattlingPVPInfoDialog:ResetSkillCards()
    if isNull(self.listEnemySkillCard) then return end
    for i = 1, #self.listEnemySkillCard do        
        self.listEnemySkillCard[i]:SetSequeneSkillCardDefaut()
    end
end

function UIBattlingPVPInfoDialog:DOFuncAtBattleMyCard(data)
    if isNull(self.listSkillCardData) then
        self.listSkillCardData = {}
    end
    if data.r == Constants.RecordType.UseCard then
        if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
            self:SetSkillCardData(data)
        else
            table.insert(self.listSkillCardData, data)
        end
    end
end

function UIBattlingPVPInfoDialog:SetSkillCardData(data)
    self.curAction = self.curAction + 1
    if self.curAction <= #self.listEnemySkillCard then
        local skillData, catId
        if UIBattlingDataMgr:IsSkillCat(data.ri) then
            catId = UIBattlingDataMgr:GetCatIdById(data.ri)
            if data.si == 0 then
                skillData = UIBattlingDataMgr:GetCatFinalSkillData(data.ri, data.si)
            end
        else
            skillData = UIBattlingDataMgr:GetSkillIdByCamp(BattleInfo.otherCamp, data.ri, data.si)
        end
        local skillId = skillData.skillId
        local skillLevel = skillData.skillLv
        local cardData = {roleId = data.ri, skillId = skillId , star = data.s , skillLv = skillLevel, skillIndex = data.si, catId = catId}
        if self.listEnemySkillCard[self.curAction] then
            self.listEnemySkillCard[self.curAction]:ShowSequeneSkillCard({ cardData = cardData, nil, nil })
        end
    end
end

function UIBattlingPVPInfoDialog:SetListSkillData()
    local _APEnemy = UIBattlingPVPMgr.enemyActionPoint
    local list2Show = {}
    for i = 1, _APEnemy do
        table.insert(list2Show, self.listSkillCardData[i])
    end
    -- print("->UIBattlingPVPInfoDialog:SetListSkillData:", table.dump(list2Show))
    for i, data in pairs(list2Show) do
        self:SetSkillCardData(data)
    end
end

function UIBattlingPVPInfoDialog:ActionOnInputFinished()
    if BattleInfo.gameMode == Constants.GameMode.PVE and UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        self:SetListSkillData()
    end
end

