end

function UIBattlingPVPInfoDialog:PlayAnimation(name)
    if not isNull(self.PVPTimerNode) then
        self.PVPTimerNode:Play(name,0,0)
        self.PVPTimerNode:Update(0)
    end
end

function UIBattlingPVPInfoDialog:SetTimerValue(value)
    xTry(function()
        value = checkNumber(value)
        local condition = IsNull(self.Txt_Num2) or IsNull(self.Txt_Num1) or IsNull(self.Txt_Num) or IsNull(self.PVPTimerNode) or isNull(self.indexAnimationName)
        if condition then return end
        local index = value >= 5 and 1 or 2
        if value >= 5 then
            KTool.SetActive(self.TimeGroup1.gameObject, true)
            if self.indexAnimationName < 1 then
                self.indexAnimationName = index
                self:PlayAnimation(PVP_TIMER_ANIMATIONS.Default)
            end
            self.Txt_Num.text = checkString(value)
        else
            if isNull(self.valueSaved) then self.valueSaved = 0 end
            if isNull(self.valueEx) then self.valueEx = 0 end
            local valuePre = self.valueEx - value
            self.valueSaved = self.valueSaved + valuePre
            if self.valueSaved >= 1 then
                self:PlayAnimation(PVP_TIMER_ANIMATIONS.Switch)
                self.valueSaved = 0
            end
            KTool.SetActive(self.TimeGroup2.gameObject, true)
            self.Txt_Num1.text = checkString(value)
            self.Txt_Num2.text = checkString(value)
        end
        self.valueEx = value
        if value <= 0 then
            KTool.SetActive(self.TimeGroup1.gameObject, false)
            KTool.SetActive(self.TimeGroup2.gameObject, false)
        end
    end)
end

