function UIBattlingPVPInfoDialog:OnReceivedPackage(packageId, packageData)
    if not UIBattlingTools.IsMyPlayerId(packageData.playerId) then return end
    -- 点击手动退出以后，服务器会下发托管，这里屏蔽托管界面，防止返回主界面以后，托管界面才打开
    if isNotNull(BattleViewMgr.requestManualExit) and BattleViewMgr.requestManualExit == true then return end

    local ReceivePackageIds = BattleViewMgr.netMgr.ReceivePackageIds
    if packageId == ReceivePackageIds.PlayerHosting then
        if packageData.isOpen == 1 then
            UIModule.OpenDialog({ id = Constants.UITypeIds.CommonHostingDialog })
        end
    end
end

function UIBattlingPVPInfoDialog:ActionOnBattleRequireInput()
    if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PPVE then
        if UIBattlingTools:GetMyCampPlayerCount() == 2 then
            self:SetPlayerHeadNodeState(true)
        end
    elseif UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        self:SetPlayerHeadNodeState(true)
    end
end

function UIBattlingPVPInfoDialog:ActionOnAllCampInputFinish()
    if UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PPVE then
        if UIBattlingTools:GetMyCampPlayerCount() == 2 then
            self:SetPlayerHeadNodeState(false)
        end
    elseif UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        self:SetPlayerHeadNodeState(false)
    end
end

function UIBattlingPVPInfoDialog:SetPlayerHeadNodeState(state)
    KTool.SetActive(self.RT_PlayerHeadNode1.gameObject, state)
    KTool.SetActive(self.RT_PlayerHeadNode2.gameObject, state)
end

return UIBattlingPVPInfoDialog